  to { transform: rotate(360deg); }
}

/* App Loading State */
.app-loading {
  position: fixed;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  background: linear-gradient(135deg, #0A0B10 0%, #0C0F17 100%);
